// API response types come from the OpenAPI document (src/api/schema.d.ts, generated by `npm run gen:api` from
// src/SarawakBizOps.Api/openapi.json, which the API's tests keep current). The aliases below give them the names the
// app uses and, where the server sends a plain string from a known set (a status, a priority), narrow it to that set.
// Request bodies, filters and UI-only types are written by hand.
import type { components } from '../api/schema'

type Schemas = components['schemas']
/** T with some properties' types replaced (narrowed). */
type With<T, U extends Partial<Record<keyof T, unknown>>> = Omit<T, keyof U> & U

export type CurrentUser = Schemas['CurrentUserResponse']

export type LoginResult = Schemas['LoginResponse']

export type Customer = Schemas['CustomerDto']

export interface CustomerInput {
  companyName: string
  contactPerson?: string
  phone?: string
  email?: string
  address?: string
}

export type EquipmentStatus = 'Active' | 'Inactive' | 'UnderMaintenance' | 'Retired'

export type Equipment = With<Schemas['EquipmentDto'], { status: EquipmentStatus }>

export interface EquipmentInput {
  customerId: number
  serialNumber: string
  equipmentType: string
  brand?: string
  model?: string
  installationDate?: string
  location?: string
}

export interface EquipmentUpdateInput {
  serialNumber: string
  equipmentType: string
  brand?: string
  model?: string
  installationDate?: string
  location?: string
  status: EquipmentStatus
}

export const ROLES = ['Admin', 'Manager', 'ServiceStaff', 'Technician', 'WarehouseStaff'] as const
export type RoleName = (typeof ROLES)[number]

export type UserSummary = Schemas['UserDto']

export interface CreateUserInput {
  fullName: string
  email: string
  password: string
  role: string
}

export interface UpdateUserInput {
  fullName?: string
  role?: string
  isActive?: boolean
}

export type ServiceHistoryItem = Schemas['ServiceHistoryItemDto']

export type ServiceHistory = Schemas['ServiceHistoryDto']

export const REQUEST_STATUSES = ['New', 'Approved', 'Assigned', 'Rejected', 'Cancelled'] as const
export type ServiceRequestStatus = (typeof REQUEST_STATUSES)[number]

export const REQUEST_PRIORITIES = ['Low', 'Medium', 'High', 'Urgent'] as const
export type RequestPriority = (typeof REQUEST_PRIORITIES)[number]

export type ServiceRequest = With<
  Schemas['ServiceRequestDto'],
  { priority: RequestPriority; status: ServiceRequestStatus }
>

export interface ServiceRequestInput {
  customerId: number
  equipmentId: number
  problemDescription: string
  priority: RequestPriority
}

export interface ServiceRequestFilters {
  status?: ServiceRequestStatus | ''
  priority?: RequestPriority | ''
  customerId?: number | ''
}

export const WORK_ORDER_STATUSES = [
  'Assigned',
  'InProgress',
  'PendingParts',
  'Completed',
  'Approved',
  'Cancelled'
] as const
export type WorkOrderStatus = (typeof WORK_ORDER_STATUSES)[number]

export type WorkOrder = With<Schemas['WorkOrderDto'], { priority: RequestPriority; status: WorkOrderStatus }>

/** One part line on a job; `id` is the line id used to return it. Prices are snapshotted server-side. */
export type WorkOrderPart = Schemas['WorkOrderPartDto']

/** One photo on a job. `contentType` was decided by the server from the file's bytes. */
export type WorkOrderPhoto = Schemas['WorkOrderPhotoDto']

/** Phase 10: a job's service report. One per job; regenerating keeps the number and bumps the revision. */
export type ServiceReportSummary = Schemas['ServiceReportSummaryDto']

/** One row of the Reports page. */
export type ServiceReport = With<Schemas['ServiceReportDto'], { workOrderStatus: WorkOrderStatus }>

export interface PendingPartsInput {
  reason: string
  partId: number
  quantity: number
  rowVersion: string
}

export interface DiagnosisInput {
  diagnosis: string
  workPerformed: string
  notes?: string
  rowVersion: string
}

export interface WorkOrderFilters {
  status?: WorkOrderStatus | ''
}

export type Technician = Schemas['TechnicianSummaryDto']

// ---- Phase 6: parts and the inventory ledger ----

export type Part = Schemas['PartDto']

// No quantityOnHand: stock only ever changes through a ledger movement (BR-09).
export interface PartInput {
  partNumber: string
  name: string
  description?: string
  unit: string
  unitCost: number
  minimumStockLevel: number
}

export interface PartUpdateInput extends PartInput {
  isActive: boolean
  rowVersion: string
}

export interface PartFilters {
  search?: string
  includeInactive?: boolean
  /** 1-based. */
  page?: number
  pageSize?: number
}

/** One page of a list browsed by page number (GET /parts). */
export type PagedResult<T> = With<Schemas['PartDtoPagedResult'], { items: T[] }>

/** One page of a list read forwards (GET /inventory-transactions); pass nextCursor back for the next page. */
export type CursorPage<T> = With<Schemas['InventoryTransactionDtoCursorPage'], { items: T[] }>

export const TRANSACTION_TYPES = ['Receive', 'Issue', 'Return', 'Adjustment'] as const
export type InventoryTransactionType = (typeof TRANSACTION_TYPES)[number]

/** What the warehouse may raise directly; Issue/Return come only from work-order parts. */
export type StockMovementType = Extract<InventoryTransactionType, 'Receive' | 'Adjustment'>

export interface StockMovementInput {
  partId: number
  transactionType: StockMovementType
  quantity: number
  notes?: string
}

export type InventoryTransaction = With<
  Schemas['InventoryTransactionDto'],
  { transactionType: InventoryTransactionType }
>

export interface TransactionFilters {
  partId?: number | ''
  type?: InventoryTransactionType | ''
  workOrderId?: number | ''
  /** MYT calendar days, yyyy-mm-dd, inclusive at both ends. */
  fromDate?: string
  toDate?: string
}

// ---- Phase 11: the Manager dashboard (GET /api/dashboard/summary) ----

export type CountByKey = Schemas['CountDto']

export type MonthCount = Schemas['MonthCountDto']

export type LowStockItem = Schemas['LowStockItemDto']

export type AnalyticsPeriod = Schemas['AnalyticsPeriodDto']

export type DurationStat = Schemas['DurationStatDto']

export type RepeatedFailure = Schemas['RepeatedFailureDto']

export type PartUsage = Schemas['PartUsageDto']

export type LowStockSummary = Schemas['LowStockSummaryDto']

// Phase 12: GET /api/dashboard/summary answers with the caller's own view, tagged by `view`.
export type DashboardView = ManagerDashboard | WarehouseDashboard | ServiceQueueDashboard

export type ManagerDashboard = With<Schemas['DashboardSummaryDto'], { view: 'Manager' }>

export type JobWaitingForPart = Schemas['JobWaitingForPartDto']

export type WarehouseDashboard = With<Schemas['WarehouseDashboardDto'], { view: 'Warehouse' }>

export type QueuedRequest = With<
  Schemas['QueuedRequestDto'],
  { priority: RequestPriority; status: ServiceRequestStatus }
>

export type RejectedRequest = Schemas['RejectedRequestDto']

export type ServiceQueueDashboard = With<
  Schemas['ServiceQueueDashboardDto'],
  {
    view: 'ServiceQueue'
    queue: With<Schemas['RequestQueueDto'], { oldestOpen: QueuedRequest[] }>
  }
>

// ---- Phase 13: the AI technician assistant (AI-01) ----

export type AssistantLikelihood = 'High' | 'Medium' | 'Low'

export type AssistantCause = With<Schemas['AssistantCauseDto'], { likelihood: AssistantLikelihood }>

// An earlier job on the same equipment: the facts come from the database, only whyRelevant from the model.
export type AssistantPastCase = Schemas['AssistantPastCaseDto']

export type AssistantPart = Schemas['AssistantPartDto']

// Suggestions only — nothing in it is ever applied to the job. The disclaimer is set by the server on every answer.
export type TechnicianAssistance = With<Schemas['TechnicianAssistanceDto'], { possibleCauses: AssistantCause[] }>

// ---- Phase 14: AI Manager Insights (AI-02, AC-10) ----

export type ManagerInsightTopic = Schemas['ManagerInsightTopicDto']

export type ManagerInsightFigure = Schemas['ManagerInsightFigureDto']

/**
 * The server answers every question with 200: `Answered` (the figures, and the model's wording of them when it gave
 * a usable one) or `Refused` (why, and what can be asked instead).
 */
export type ManagerInsight = With<Schemas['ManagerInsightDto'], { outcome: 'Answered' | 'Refused' }>
